package net.minecraft.client;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.player.Player; public final class Minecraft {private static final Minecraft INSTANCE=new Minecraft();public ClientLevel level;public Player player;public Object connection=new Object(),screen;public Entity camera;public boolean paused,active=true,defer;public final java.util.ArrayDeque<Runnable> queued=new java.util.ArrayDeque<>();public static Minecraft getInstance(){return INSTANCE;}public Object getConnection(){return connection;}public boolean hasSingleplayerServer(){return false;}public boolean isWindowActive(){return active;}public boolean isPaused(){return paused;}public Entity getCameraEntity(){return camera==null?player:camera;}public void execute(Runnable r){if(defer)queued.add(r);else r.run();}public void drain(){while(!queued.isEmpty())queued.removeFirst().run();}}
